using PdfSharp.Pdf;using PdfSharp.Pdf.IO;using ProformaViewer.Models;
namespace ProformaViewer.Services;
public sealed record ExportResult(int PageCount,IReadOnlyList<string> Errors);
public sealed class PdfExportService { public Task<ExportResult> ExportAsync(IEnumerable<ProformaEntry> entries,string destination,IProgress<int>? progress=null)=>Task.Run(()=>Export(entries,destination,progress)); static ExportResult Export(IEnumerable<ProformaEntry> source,string destination,IProgress<int>? progress){var entries=source.ToList();var errors=new List<string>();using var output=new PdfDocument();var done=0;var total=Math.Max(1,entries.Sum(e=>e.Pages.Count));foreach(var entry in entries){if(!System.IO.File.Exists(entry.Path)){errors.Add($"{entry.Title}: PDF not found: {entry.Path}");done+=entry.Pages.Count;progress?.Report(Math.Min(100,done*100/total));continue;}try{using var input=PdfReader.Open(entry.Path,PdfDocumentOpenMode.Import);foreach(var page in entry.Pages){if(page<1||page>input.PageCount)errors.Add($"{entry.Title}: page {page} is outside range 1-{input.PageCount}.");else output.AddPage(input.Pages[page-1]);done++;progress?.Report(Math.Min(100,done*100/total));}}catch(Exception ex){errors.Add($"{entry.Title}: {ex.Message}");done+=entry.Pages.Count;progress?.Report(Math.Min(100,done*100/total));}}var count=output.Pages.Count;if(count==0)throw new InvalidOperationException("No valid pages could be exported."+(errors.Count>0?Environment.NewLine+string.Join(Environment.NewLine,errors):""));var folder=System.IO.Path.GetDirectoryName(destination);if(!string.IsNullOrWhiteSpace(folder))System.IO.Directory.CreateDirectory(folder);output.Save(destination);progress?.Report(100);return new(count,errors);} }
